// Core tests: the 24 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every expected value below was computed by hand from the SPEC's
// rules; the hand derivations are listed in AUTHOR-CHECK.md section 2.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatDistanceM,
  formatDuration,
  formatVo2max,
  run,
} from "../public/js/core/vo2max.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = { test: "cooper12", distanceMeters: "2400", time: "12:00", age: "", sex: "" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchors: Cooper 2800 m is 51.3 and 1.5-mile 15:00 is 35.7", () => {
  assert.equal(run({ ...base, distanceMeters: "2800" }).result.vo2max, 51.3);
  const mile = run({ ...base, test: "mile15", time: "15:00" });
  assert.equal(mile.ok, true);
  assert.equal(mile.result.vo2max, 35.7);
  assert.equal(mile.result.timeSeconds, 900);
});

test("boundary: 507.2 m is the first success at 0.1; 505, 506 and 507.1 m are BELOW_RANGE", () => {
  // SPEC section 4 step 4 states "506 m gives 0.1", but the pinned
  // formula says otherwise: (506 - 504.9) / 44.73 = 0.0246..., which
  // rounds to 0.0, so the pinned non-positive rule fires. The first
  // distance that rounds to 0.1 is 507.2 m. The implementation follows
  // the normative formula and rounding rule; see HANDOFF.md errata 1.
  const ok = run({ ...base, distanceMeters: "507.2" });
  assert.equal(ok.ok, true);
  assert.equal(ok.result.vo2max, 0.1);
  for (const distance of ["505", "506", "507", "507.1"]) {
    assert.deepEqual(errorOf({ ...base, distanceMeters: distance }), {
      code: "BELOW_RANGE",
      field: "distanceMeters",
      row: null,
    });
  }
});

test("boundary: time 4:00 succeeds, 3:59 is RANGE; 60:00 succeeds, 60:01 is RANGE", () => {
  const fast = run({ ...base, test: "mile15", time: "4:00" });
  assert.equal(fast.ok, true);
  assert.equal(fast.result.timeSeconds, 240);
  assert.equal(fast.result.vo2max, 124.3);
  assert.deepEqual(errorOf({ ...base, test: "mile15", time: "3:59" }), {
    code: "RANGE",
    field: "time",
    row: null,
  });
  const slow = run({ ...base, test: "mile15", time: "60:00" });
  assert.equal(slow.ok, true);
  assert.equal(slow.result.timeSeconds, 3600);
  assert.equal(slow.result.vo2max, 11.6);
  assert.deepEqual(errorOf({ ...base, test: "mile15", time: "60:01" }), {
    code: "RANGE",
    field: "time",
    row: null,
  });
});

test("boundary: age 13 and 99 classify, 12 and 100 are RANGE", () => {
  const young = run({ ...base, age: "13", sex: "female" });
  assert.equal(young.ok, true);
  assert.equal(young.result.classification.ageBand, "13-19");
  const old = run({ ...base, age: "99", sex: "male" });
  assert.equal(old.ok, true);
  assert.equal(old.result.classification.ageBand, "60+");
  assert.deepEqual(errorOf({ ...base, age: "12", sex: "male" }), {
    code: "RANGE",
    field: "age",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, age: "100", sex: "male" }), {
    code: "RANGE",
    field: "age",
    row: null,
  });
});

test("capacity: a 9-unit value is INPUT_LIMIT on every field, including inactive ones", () => {
  assert.deepEqual(errorOf({ ...base, test: "cooper12x" }), {
    code: "INPUT_LIMIT",
    field: "test",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, distanceMeters: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "distanceMeters",
    row: null,
  });
  // Inactive time field: still capacity-checked in cooper12 mode.
  assert.deepEqual(errorOf({ ...base, time: "12:00:000" }), {
    code: "INPUT_LIMIT",
    field: "time",
    row: null,
  });
  // Inactive distance field: still capacity-checked in mile15 mode.
  assert.deepEqual(errorOf({ ...base, test: "mile15", distanceMeters: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "distanceMeters",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, age: "123456789", sex: "male" }), {
    code: "INPUT_LIMIT",
    field: "age",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, age: "30", sex: "female123" }), {
    code: "INPUT_LIMIT",
    field: "sex",
    row: null,
  });
});

test("an inactive field is capacity- and surrogate-checked but otherwise ignored", () => {
  // A lone surrogate in the inactive time field is UNICODE.
  assert.deepEqual(errorOf({ ...base, time: "\uD800" }), {
    code: "UNICODE",
    field: "time",
    row: null,
  });
  // Arbitrary text in the inactive distance field is ignored entirely.
  const ignored = run({ ...base, test: "mile15", distanceMeters: "abc" });
  assert.equal(ignored.ok, true);
  assert.equal(ignored.result.vo2max, 43.8);
  // And arbitrary text in the inactive time field is ignored in cooper12.
  const ignoredTime = run({ ...base, time: "garbage!" });
  assert.equal(ignoredTime.ok, true);
  assert.equal(ignoredTime.result.vo2max, 42.4);
});

test("an active field reports UNICODE before EMPTY and grammar", () => {
  assert.deepEqual(errorOf({ ...base, distanceMeters: "\uD800" }), {
    code: "UNICODE",
    field: "distanceMeters",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, test: "mile15", time: "\uD800" }), {
    code: "UNICODE",
    field: "time",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, distanceMeters: "" }), {
    code: "EMPTY",
    field: "distanceMeters",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, test: "mile15", time: "" }), {
    code: "EMPTY",
    field: "time",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, test: "" }), {
    code: "EMPTY",
    field: "test",
    row: null,
  });
});

test("distance grammar: signs, exponents, commas, two decimals and non-ASCII digits are DECIMAL_FORMAT", () => {
  for (const bad of ["-100", "+100", "1e3", "2,400", "2400.55", "2400.", ".5", "２４００", "2400 "]) {
    assert.deepEqual(errorOf({ ...base, distanceMeters: bad }), {
      code: "DECIMAL_FORMAT",
      field: "distanceMeters",
      row: null,
    });
  }
  const leadingZero = run({ ...base, distanceMeters: "02400.0" });
  assert.equal(leadingZero.ok, true);
  assert.equal(leadingZero.result.distanceMeters, 2400);
  const max = run({ ...base, distanceMeters: "10000" });
  assert.equal(max.ok, true);
  assert.equal(max.result.vo2max, 212.3);
  assert.deepEqual(errorOf({ ...base, distanceMeters: "10000.1" }), {
    code: "RANGE",
    field: "distanceMeters",
    row: null,
  });
});

test("time grammar: single-digit seconds, fractional seconds and bad shapes are TIME_FORMAT", () => {
  for (const bad of ["12:0", "12:000", "12.00", "12:60", "1:2:3", "1234:00", "1:00:60"]) {
    assert.deepEqual(errorOf({ ...base, test: "mile15", time: bad }), {
      code: "TIME_FORMAT",
      field: "time",
      row: null,
    });
  }
  const hms = run({ ...base, test: "mile15", time: "1:00:00" });
  assert.equal(hms.ok, true);
  assert.equal(hms.result.timeSeconds, 3600);
});

test("age grammar and sex enum: non-digits are INTEGER_FORMAT, other sex values are ENUM", () => {
  assert.deepEqual(errorOf({ ...base, age: "30.5", sex: "male" }), {
    code: "INTEGER_FORMAT",
    field: "age",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, age: "abc", sex: "male" }), {
    code: "INTEGER_FORMAT",
    field: "age",
    row: null,
  });
  const leadingZeroAge = run({ ...base, age: "030", sex: "female" });
  assert.equal(leadingZeroAge.ok, true);
  assert.equal(leadingZeroAge.result.classification.ageBand, "30-39");
  assert.deepEqual(errorOf({ ...base, age: "30", sex: "other" }), {
    code: "ENUM",
    field: "sex",
    row: null,
  });
});

test("pair rule fires after per-field checks and names the absent field", () => {
  assert.deepEqual(errorOf({ ...base, age: "30" }), {
    code: "PAIR_REQUIRED",
    field: "sex",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, sex: "male" }), {
    code: "PAIR_REQUIRED",
    field: "age",
    row: null,
  });
  // A field error earlier in field order wins over the pair rule.
  assert.deepEqual(errorOf({ ...base, distanceMeters: "10001", age: "30" }), {
    code: "RANGE",
    field: "distanceMeters",
    row: null,
  });
  // An out-of-range age wins over the pair rule (age is checked first).
  assert.deepEqual(errorOf({ ...base, age: "12" }), {
    code: "RANGE",
    field: "age",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, test: "rockport", distanceMeters: "bad" }), {
    code: "ENUM",
    field: "test",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, distanceMeters: "bad", time: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "distanceMeters",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, test: "mile15", time: "bad", age: "12" }), {
    code: "TIME_FORMAT",
    field: "time",
    row: null,
  });
});

test("classification boundaries: a rounded value exactly on a threshold takes the upper band", () => {
  // Men 20-29 goodMin is 42.5; the 2404.4 m fixture pins this. Here the
  // same band edge is reached from the mile side: 12:00 gives 43.8,
  // which is above goodMin 42.5 and below excellentMin 46.5.
  const outcome = run({ ...base, test: "mile15", time: "12:00", age: "25", sex: "male" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.vo2max, 43.8);
  assert.equal(outcome.result.classification.category, "good");
  // Women 60+ superiorMin is 31.5: 31.5 is superior, 31.4 is excellent.
  // 1900.5 m for a 52-year-old man is 31.2 (fair) per the fixture; a
  // 60-year-old woman at 2000 m is 33.4, above superiorMin 31.5.
  const senior = run({ ...base, distanceMeters: "2000", age: "65", sex: "female" });
  assert.equal(senior.ok, true);
  assert.equal(senior.result.classification.category, "superior");
  // Just below a threshold stays in the lower band: men 30-39 fairMin
  // is 35.5; 35.4 is poor. 2100 m gives (2100-504.9)/44.73 = 35.66...
  // -> 35.7, so use 2080 m: (2080-504.9)/44.73 = 35.21... -> 35.2.
  const below = run({ ...base, distanceMeters: "2080", age: "35", sex: "male" });
  assert.equal(below.ok, true);
  assert.equal(below.result.vo2max, 35.2);
  assert.equal(below.result.classification.category, "poor");
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.time;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, distanceMeters: 2400 }), schema);
  assert.deepEqual(errorOf({ ...base, age: null }), schema);
  assert.deepEqual(errorOf(["cooper12"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("cooper12"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "distanceMeters", {
    enumerable: true,
    get() {
      return "2400";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.distanceMeters = new String("2400");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...base, age: "35", sex: "male" };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, distanceMeters: "10001" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("property: vo2max never decreases as Cooper distance grows, and never increases as mile time grows", () => {
  let previous = -Infinity;
  for (const distance of [600, 1000, 1500, 2000, 2400, 3000, 5000, 10000]) {
    const outcome = run({ ...base, distanceMeters: String(distance) });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.vo2max >= previous);
    previous = outcome.result.vo2max;
  }
  previous = Infinity;
  for (const time of ["4:00", "8:00", "12:00", "20:00", "30:00", "60:00"]) {
    const outcome = run({ ...base, test: "mile15", time });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.vo2max <= previous);
    previous = outcome.result.vo2max;
  }
});

test("display formatting: vo2max one decimal, durations, grouped distances", () => {
  assert.equal(formatVo2max(42.4), "42.4");
  assert.equal(formatVo2max(45), "45.0");
  assert.equal(formatVo2max(11.6), "11.6");
  assert.equal(formatDuration(0), "0:00");
  assert.equal(formatDuration(59), "0:59");
  assert.equal(formatDuration(60), "1:00");
  assert.equal(formatDuration(720), "12:00");
  assert.equal(formatDuration(3599), "59:59");
  assert.equal(formatDuration(3600), "1:00:00");
  assert.equal(formatDistanceM(400), "400");
  assert.equal(formatDistanceM(2400), "2,400");
  assert.equal(formatDistanceM(2404.4), "2,404.4");
  assert.equal(formatDistanceM(10000), "10,000");
});
